#!/usr/bin/env node
/* global process, console */
// Generates packages/shared/src/trig-tables.ts (integer sin/atan tables) with Math.sin/Math.atan.
// This script is OUTSIDE lint:sim on purpose; the generated file is a committed literal.
// Usage: node tools/gen-trig.mjs            write the file
//        node tools/gen-trig.mjs --check    exit 1 if the committed file differs from the output
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import * as prettier from 'prettier';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const target = path.join(root, 'packages/shared/src/trig-tables.ts');

const TRIG_ONE = 16384;
const ANGLE_STEPS = 1024;
const sin = [];
const atan = [];
for (let i = 0; i <= 256; i++) {
  sin.push(Math.round(TRIG_ONE * Math.sin((i * 2 * Math.PI) / ANGLE_STEPS)));
  atan.push(Math.round((ANGLE_STEPS / (2 * Math.PI)) * Math.atan(i / 256)));
}

const raw = `// GENERATED by tools/gen-trig.mjs - do not edit by hand. Changing any value breaks replay
// compatibility (ADR-005 §2): bump REPLAY_FORMAT_VERSION and re-pin the hashes in trig.test.ts.

/** round(16384 * sin(i * 2π / 1024)), i = 0..256 (one quarter wave). */
export const SIN_QUARTER: readonly number[] = [${sin.join(', ')}];

/** round(1024 / (2π) * atan(i / 256)), i = 0..256 (first octant, 0..128). */
export const ATAN_OCTANT: readonly number[] = [${atan.join(', ')}];
`;

const config = (await prettier.resolveConfig(target)) ?? {};
const out = await prettier.format(raw, { ...config, filepath: target });

if (process.argv.includes('--check')) {
  const cur = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
  if (cur !== out) {
    console.error('trig-tables.ts is out of date; run: node tools/gen-trig.mjs');
    process.exit(1);
  }
  console.log('trig-tables.ts up to date');
} else {
  fs.writeFileSync(target, out);
  console.log(`wrote ${path.relative(root, target)}`);
}
